// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog as C} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(address _caller) internal {
        vm.assume(!c.approvedLoggers(_caller));
        bool obs = c.approvedToLog(_caller);
        assertTrue(!obs);
    }

    function testFuzz_run(address _caller) public {
        _caller = address(uint160(bound(uint256(uint160(_caller)), 0xffff + 1, type(uint160).max)));
        vm.assume(_caller.code.length == 0 && _caller != address(this) && _caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _caller != 0x000000000000000000636F6e736F6c652e6c6f67 && _caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_caller);
    }
}
